{"command": "python3 - <<'EOF'
import socket, concurrent.futures
# scan full 172.26.0.0/16 quickly on a few common ports with short timeout
def tryhost(ip):
    for p in (80, 8080, 8000):
        try:
            s = socket.create_connection((ip, p), timeout=0.4)
            s.close()
            return (ip, p)
        except Exception:
            pass
    return None
hosts = [f"172.26.{a}.{b}" for a in range(0,4) for b in range(1,255)]
with concurrent.futures.ThreadPoolExecutor(200) as ex:
    for r in ex.map(tryhost, hosts):
        if r: print("OPEN", r)
print("scan done")
EOF"}

